import json
from pathlib import Path
w=Path('/tmp/claim-audit-ynnm_m6u');r=json.loads((w/'input/report-ledger.json').read_text());s=json.loads((w/'input/source-ledger.json').read_text())
def ev(a):
 for p,aa in s.items():
  if a in aa:return {'path':p,'anchor':a,'quote':aa[a]}
 raise ValueError(a)
def proof(t,target,relation='supports'):return {'module':'Audit','theorem':'Audit.'+t,'relation':relation,'target':target}
f=[]
def add(n,q,anchors,rules,reason,formal,proofs,limits,reco,assumptions=None):
 k=f'VD-C{n:02d}'
 f.append({'claim_id':k,'report_anchor':k,'report_quote':r[k],'question':q,'evidence':[ev(a) for a in anchors],'rules':rules,'assumptions':assumptions if assumptions is not None else ['Accepted receipts, case classes and submissions are transcribed faithfully from the supplied register; documentary assertions are used within the fictional W-6 mandate without independent authentication.','Gregorian UTC date conversion and the day-zero, inclusive 17:00 convention in B02 apply; no business-day adjustment is introduced.'],'reasoning':[str(i+1)+'. '+v for i,v in enumerate(reason)],'semantic_state':'supported','argument_status':'sufficient','formal_status':formal,'proofs':proofs,'limits':limits,'recommendation':reco})
add(1,'Does D-201 retain revision 1 despite March 1 assignment, and does its February 20 receipt yield a March 1 17:00 inclusive deadline met exactly by its actual submission?', ['C01','V1-01','V1-02','V2-01'],['V1-01 and V2-01 select the revision using accepted receipt and preserve revision 1 for earlier receipts.','V1-02 adds ten calendar dates from receipt date as day zero and sets an inclusive 17:00 UTC cutoff with no holiday adjustment.'],['C01 records a standard case received February 20 at 09:00, before the March 1 boundary; later assignment does not alter revision 1 applicability.','2028 includes February 29. Adding ten dates to February 20 gives March 1, not March 2. Independently executed datetime arithmetic confirms the cutoff offset 15420.','The submission is March 1 at 17:00, exactly that cutoff. Inclusive comparison establishes timeliness. All three report components are supported.'],'proved',[proof('claim01','Audit.revision Audit.d201 = .one ∧ Audit.standardDeadline Audit.d201 = some 15420 ∧ Audit.d201.submitted = 15420 ∧ Audit.d201.submitted ≤ 15420')],['Lean checks integer arithmetic after source/calendar transcription, not a standalone Gregorian calendar implementation or source authenticity.'],'Retain and cite accepted receipt, the transition rule, and the leap-year day-zero calculation.')
add(2,'Does D-202 accepted receipt at 2028-02-29 23:59 select revision 1, exactly one minute before the March 1 boundary, irrespective of later internal assignment?', ['C02','V1-01','V2-01','T01'],['Intake accepted receipt determines applicability. Earlier receipts retain revision 1 even after later assignment, review or submission; T01 labels do not override this.'],['C02 gives accepted receipt at February 29 23:59 and assignment at March 1 08:30.','The receipt minute offset 14399 is one less than the transition offset 14400, so it is strictly before the boundary and revision 1 applies.','The revision function depends only on accepted receipt. Changing assignment alone cannot change its result; the formal target quantifies over assignment values.','T01 is a display field rather than a receipt correction, so it supplies no competing authoritative version assignment.'],'proved',[proof('claim02','Audit.revision Audit.d202 = .one ∧ Audit.d202.received + 1 = Audit.boundary ∧ (∀ a, Audit.revision (Audit.withAssignment Audit.d202 a) = .one)')],['Assignment invariance is about the supplied transition rule, not a general principle for other workflows.'],'Retain the one-minute distinction and make the accepted-receipt basis explicit.')
add(3,'Under the applicable revision 1 standard rule, is D-202 deadline March 10 17:00 UTC and its March 10 17:01 submission late?', ['C02','V1-01','V1-02','V2-01'],['Revision 1 remains applicable to receipt before the boundary; its standard deadline is receipt date plus ten calendar days at inclusive 17:00 UTC.'],['D-202 is standard and its February 29 23:59 accepted receipt precedes the boundary.','Receipt day is February 29 regardless of its late hour. Adding ten calendar dates gives March 10; the cutoff is 17:00, offset 28380.','C02 records submission at 17:01 that day, offset 28381. The submission exceeds the inclusive cutoff by one minute and is late.'],'proved',[proof('claim03','Audit.standardDeadline Audit.d202 = some 28380 ∧ 28380 < Audit.d202.submitted')],['The computation is calendar dates from receipt date, not ten rolling 24-hour periods from 23:59. No real regulatory conclusion is implied.'],'Retain the deadline and lateness with the one-minute calculation.')
add(4,'Does D-203 exact-boundary accepted receipt select revision 2, produce March 8 17:00 UTC as its seven-calendar-day deadline, and make the equal-time submission timely?', ['C03','V2-01','V2-02'],['V2-01 includes the boundary instant in revision 2. V2-02 applies a seven-calendar-day standard cutoff at inclusive 17:00 UTC.'],['C03 records a standard case with accepted receipt exactly March 1 00:00, the revision boundary; at-or-after includes equality.','March 1 plus seven calendar dates is March 8. The 17:00 cutoff is offset 25500.','C03 records submission exactly March 8 at 17:00, so it is timely at the inclusive endpoint.'],'proved',[proof('claim04','Audit.d203.received = Audit.boundary ∧ Audit.revision Audit.d203 = .two ∧ Audit.standardDeadline Audit.d203 = some 25500 ∧ Audit.d203.submitted = 25500 ∧ Audit.d203.submitted ≤ 25500')],['The equality result depends on both explicitly inclusive boundaries: the revision transition and submission cutoff.'],'Retain both equality-boundary explanations.')
add(5,'Does the supplied dashboard revision field describe the active revision at export rather than per-case applicability?', ['T01','V1-01','V2-01','C01','C02','C03','C04'],['The V2-01 transition clause supersedes informal dashboard labels. T01 explicitly defines the field as current active revision and says it is not a receipt correction.'],['T01 states that all four cases display revision 2 on March 15 and directly explains the display semantics.','Applicable versions still derive from accepted receipt: D-201 and D-202 retain revision 1 while D-203 and D-204 use revision 2.','The explicit technical note supports the report. The finite model additionally verifies all four labels and the mismatch for the two pre-boundary cases, preventing their misinterpretation as case-level applicability evidence.'],'proved',[proof('claim05','Audit.dashboard Audit.d201 = .two ∧ Audit.dashboard Audit.d202 = .two ∧ Audit.dashboard Audit.d203 = .two ∧ Audit.dashboard Audit.d204 = .two ∧ Audit.dashboard Audit.d201 ≠ Audit.revision Audit.d201 ∧ Audit.dashboard Audit.d202 ≠ Audit.revision Audit.d202')],['The theorem verifies the finite encoded display behavior and mismatch; T01 supplies the documentary field meaning. It does not inspect a live dashboard or implementation.'],'Retain and label dashboard values as export-time metadata rather than applicable case revision.',['The T01 technical note faithfully describes this supplied export field; no broader dashboard behavior is inferred.'])
add(6,'Is D-204 restricted and therefore excluded from the revision 2 seven-day standard-case deadline rule?', ['C04','V2-01','V2-02','V2-03','V1-03'],['V2-02 is limited to standard cases. V2-03 exclusively assigns restricted deadlines and pause rules to Annex R and does not substitute the seven-day rule.'],['C04 explicitly classifies D-204 as restricted and gives March 2 receipt, after the revision boundary.','Revision 2 applies, but its standard-case duration does not: V2-03 preserves the exclusive Annex R rule for restricted cases.','The model returns no result from the standard-deadline function for this class. That expresses rule inapplicability, not absence of any actual deadline.'],'proved',[proof('claim06','Audit.d204.kind = .restricted ∧ Audit.revision Audit.d204 = .two ∧ Audit.standardDeadline Audit.d204 = none')],['No actual D-204 due date follows from this exclusion; Annex R is not supplied.'],'Retain the exclusion and avoid substituting either standard duration for Annex R.')
add(7,'Does the supplied package omit Annex R and leave D-204 final deadline and submission timeliness undetermined, rather than establishing a precise deadline or a late/timely verdict?', ['T02','C04','V1-03','V2-03'],['Restricted-case deadlines and pause rules derive exclusively from Annex R. Complete supplied-file inventory does not imply completeness of missing normative content. Timeliness requires comparing submission to an applicable final deadline.'],['T02 explicitly states Annex R was not transferred, no source supplies its duration/calendar/pause criteria, and no independent D-204 final due date is supplied.','C04 establishes the actual March 12 16:00 submission but supplies neither the missing rule nor a pause decision.','Without a final applicable deadline, submission time alone cannot settle timeliness. The report accurately describes that evidence gap.','The auxiliary model keeps package absence fixed and assigns two hypothetical due dates: March 12 17:00 makes the known submission timely; March 11 17:00 makes it late. Neither contradicts a supplied restricted-case rule because none provides a duration. These are witnesses of underdetermination, not asserted Annex R contents.'],'auxiliary',[proof('claim07Alternatives','Audit.timelyCompletion.annexTransferred = false ∧ Audit.lateCompletion.annexTransferred = false ∧ Audit.timelyCompletion.due ≠ Audit.lateCompletion.due ∧ Audit.d204.submitted ≤ Audit.timelyCompletion.due ∧ Audit.lateCompletion.due < Audit.d204.submitted','auxiliary')],['The report\'s evidential-limit assertion is supported; the underlying precise deadline and timeliness remain undetermined. Lean does not prove actual Annex R rules or either hypothetical date.'],'Retain the gap finding. Obtain Annex R and any applicable pause decisions or an independently established final due date before judging D-204 timeliness.',['The supplied-source inventory is complete for this review; absent Annex R remains unknown rather than empty.','Auxiliary candidate due dates are explicitly hypothetical completions and introduce no actual pause approval.'])
add(8,'Does the corpus establish a D-204 pause request while supplying no evidence that approval occurred?', ['C04','T02','V2-03'],['C04 identifies filing the request as the only established pause-related event. A request and a decision are distinct; the missing Annex R pause criteria cannot be invented.'],['C04 explicitly records a request filed March 4 and states that no pause decision is supplied.','T02 independently states that no source says any pause was approved for D-204.','The supplied-evidence inventory therefore contains the request and no approval evidence, directly supporting the scoped report claim.','This is not proof that approval never occurred, nor permission to add pause days when calculating an unknown deadline.'],'proved',[proof('claim08','Audit.PauseEvidence.request ∈ Audit.suppliedPauseEvidence ∧ Audit.PauseEvidence.approval ∉ Audit.suppliedPauseEvidence')],['The finite model records supplied evidence only. Actual pause approval/denial and its effect remain unknown.'],'Retain the request-versus-approval distinction and seek an actual decision together with Annex R before applying a pause.',['C04 and T02 are accepted as complete statements of the supplied pause evidence, not of all historical pause events.'])
add(9,'Do either of the two supplied rule texts define a fairness measure for comparing their timetables?', ['V1-01','V1-02','V1-03','V2-01','V2-02','V2-03','T03'],['The scope is the two supplied rule texts. A duration difference alone is not an operational fairness definition; T03 explicitly states no definition, metric, or comparison population is supplied.'],['Both complete rule texts were examined: they specify version applicability, standard timing and restricted-case delegation, but no fairness measure.','T03 attributes the informal fairer comment to the service team and explicitly confirms that neither rule defines fairness, a metric, or a comparison population.','The report is a supported descriptive claim about the absence of a definition in these texts. It does not itself assert that either timetable is fairer.'],'not_attempted',[],['No formal theorem is needed or claimed for this textual scope judgment. Whether either timetable is actually fairer remains nonformal without an agreed criterion and population.'],'Retain the scoped textual finding; require an explicit metric and population before assessing the separate informal fairness comparison.',['The complete supplied versions are the corpus being compared; no claim is made about definitions in absent external documents.'])
(w/'findings.json').write_text(json.dumps(f,indent=2,ensure_ascii=False)+'\n')
